<?php
declare(strict_types=1);
$scope = is_admin() ? '' : ' WHERE o.user_id = '.(int)$user['id'];
$orderSql = 'SELECT o.*,u.name AS user_name,s.name AS supplier_name,COALESCE((SELECT SUM(quantity*unit_price_cents) FROM order_items WHERE order_id=o.id),0) AS total FROM orders o JOIN users u ON u.id=o.user_id JOIN suppliers s ON s.id=o.supplier_id';
function order_table(array $rows): void { ?>
<div class="table-wrap"><table><thead><tr><th>Order</th><th>Supplier</th><th>Placed for</th><th>Date</th><th>Status</th><th class="number">Total</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><a class="record-link" href="index.php?page=order&id=<?= $row['id'] ?>">#<?= $row['id'] ?></a><small class="cell-note"><?= e(mb_strimwidth($row['description'],0,65,'…')) ?></small></td><td><?= e($row['supplier_name']) ?></td><td><?= e($row['user_name']) ?></td><td><?= e(str_replace('T',' ',$row['order_date'])) ?></td><td><span class="badge <?= e($row['status']) ?>"><?= e(ucfirst($row['status'])) ?></span></td><td class="number"><?= money((int)$row['total']) ?></td><td class="actions"><?php order_links((int)$row['id']); ?><?php delete_form('orders',(int)$row['id']); ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="7" class="empty">No orders yet. Create an order to get started.</td></tr><?php endif; ?></tbody></table></div>
<?php }
if ($page === 'dashboard'):
    $stats = query('SELECT COUNT(*) AS total,COALESCE(SUM(status="active"),0) AS active,COALESCE(SUM(status="ordered"),0) AS ordered,COALESCE(SUM(status="delivered"),0) AS delivered FROM orders o'.$scope)->fetch();
?>
<div class="page-heading"><div><span class="eyebrow">YOUR DAILY WORKSPACE</span><h1>Overview</h1><p class="muted">Hello, <?= e($user['name']) ?>. Here’s what’s on the menu today.</p></div><a href="index.php?page=order" class="button primary">+ New order</a></div>
<section class="welcome-banner"><div><span class="eyebrow">FROM MENU TO MEAL</span><h2>A little planning.<br>A better lunch break.</h2><p>Choose a supplier, build your order and keep everything moving.</p><a href="index.php?page=order" class="button">Create an order <span aria-hidden="true">→</span></a></div><div class="plate-art" aria-hidden="true"><div class="plate"><i></i><i></i><i></i><i></i><i></i><i></i></div><span class="art-label">Lunch is a plan.</span></div></section>
<section class="stat-grid"><?php foreach(['total'=>'All orders','active'=>'Active','ordered'=>'Ordered','delivered'=>'Delivered'] as $key=>$label): ?><a class="stat-card" href="index.php?page=orders<?= $key==='total' ? '' : '&status='.$key ?>"><span><?= $label ?></span><strong><?= (int)$stats[$key] ?></strong><small><?= $key==='active' ? 'Ready to organize' : ($key==='ordered' ? 'With your supplier' : ($key==='delivered' ? 'Enjoy your meal' : 'In your workspace')) ?></small></a><?php endforeach; ?></section>
<section class="panel"><div class="panel-heading"><div><h2>Recent orders</h2><p class="muted">The latest activity in your workspace.</p></div><a class="text-link" href="index.php?page=orders">View all orders →</a></div><?php order_table(query($orderSql.$scope.' ORDER BY o.order_date DESC,o.id DESC LIMIT 6')->fetchAll()); ?></section>
<?php elseif ($page==='orders'):
$status = is_string($_GET['status'] ?? null) ? $_GET['status'] : '';
if (!in_array($status,['active','inactive','ordered','delivered'],true)) $status='';
$search = is_string($_GET['search'] ?? null) ? mb_substr(trim($_GET['search']),0,100) : '';
$conditions=[]; $params=[];
if (!is_admin()) { $conditions[]='o.user_id=?'; $params[]=$user['id']; }
if ($status) { $conditions[]='o.status=?'; $params[]=$status; }
if ($search!=='') { $conditions[]='(s.name LIKE ? OR u.name LIKE ? OR o.description LIKE ? OR CAST(o.id AS TEXT)=?)'; array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%',$search); }
$where = $conditions ? ' WHERE '.implode(' AND ',$conditions) : '';
$count=(int)query('SELECT COUNT(*) FROM orders o JOIN users u ON u.id=o.user_id JOIN suppliers s ON s.id=o.supplier_id'.$where,$params)->fetchColumn();
$p=max(1,min(max(1,(int)ceil($count/25)),(int)($_GET['p']??1)));
$rows=query($orderSql.$where.' ORDER BY o.order_date DESC,o.id DESC LIMIT 25 OFFSET '.(($p-1)*25),$params)->fetchAll(); ?>
<div class="page-heading"><div><span class="eyebrow">PLAN · ORDER · ENJOY</span><h1>Orders</h1><p class="muted">Manage every meal, from the first item to delivery.</p></div><a href="index.php?page=order" class="button primary">+ New order</a></div>
<section class="panel"><form method="get" class="filter-bar"><input type="hidden" name="page" value="orders"><label class="search-field"><span class="sr-only">Search orders</span><input name="search" placeholder="Search supplier, user or order…" value="<?= e($search) ?>"></label><label><span class="sr-only">Status</span><select name="status"><option value="">All statuses</option><?php foreach(['active','inactive','ordered','delivered'] as $s): ?><option <?= $status===$s?'selected':'' ?>><?= $s ?></option><?php endforeach; ?></select></label><button class="button">Filter</button><a class="text-link" href="index.php?page=orders">Reset</a></form><?php order_table($rows); ?><div class="pagination"><span><?= $count ?> orders · Page <?= $p ?> of <?= max(1,(int)ceil($count/25)) ?></span><div><?php if($p>1): ?><a class="button small" href="?<?= e(http_build_query(['page'=>'orders','status'=>$status,'search'=>$search,'p'=>$p-1])) ?>">Previous</a><?php endif; ?> <?php if($p*25<$count): ?><a class="button small" href="?<?= e(http_build_query(['page'=>'orders','status'=>$status,'search'=>$search,'p'=>$p+1])) ?>">Next</a><?php endif; ?></div></div></section>
<?php elseif(in_array($page,['users','suppliers','items'],true)):
$table = ['users'=>'users','suppliers'=>'suppliers','items'=>'supplier_items'][$page];
$editId = !empty($_GET['edit']) ? positive_id($_GET['edit']) : null;
$record = $editId ? query('SELECT * FROM '.$table.' WHERE id=?',[$editId])->fetch() : [];
if($editId && !$record) throw new RuntimeException('Record not found.');
$suppliers=query('SELECT id,name FROM suppliers ORDER BY name')->fetchAll();
$filterSupplier=($page==='items' && !empty($_GET['supplier_id']))?positive_id($_GET['supplier_id']):null;
$rows=$page==='items' ? query('SELECT i.*,s.name AS supplier_name FROM supplier_items i JOIN suppliers s ON s.id=i.supplier_id'.($filterSupplier?' WHERE i.supplier_id=?':'').' ORDER BY s.name,i.name',$filterSupplier?[$filterSupplier]:[])->fetchAll() : query('SELECT * FROM '.$table.' ORDER BY name')->fetchAll();
?>
<div class="page-heading"><div><span class="eyebrow">WORKSPACE DIRECTORY</span><h1><?= e($pages[$page]) ?></h1><p class="muted"><?= $page==='items'?'Build and maintain each supplier’s menu.':($page==='users'?'Manage accounts and workspace access.':'The people who make your lunch happen.') ?></p></div><a href="#record-form" class="button primary">+ <?= $editId?'Edit record':'Add '.($page==='items'?'item':($page==='users'?'user':'supplier')) ?></a></div>
<div class="directory-grid"><section class="panel"><?php if($page==='items'): ?><form method="get" class="filter-bar"><input type="hidden" name="page" value="items"><label><span class="sr-only">Supplier</span><select name="supplier_id"><option value="">All suppliers</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>" <?= $filterSupplier===$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></label><button class="button">Filter</button></form><?php endif; ?><div class="table-wrap"><table><thead><tr><th>Name</th><th><?= $page==='items'?'Supplier': 'Phone' ?></th><th><?= $page==='items'?'Price':($page==='users'?'Role':'Comment') ?></th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['name']) ?></strong><?php if($page==='items'): ?><small class="cell-note"><?= e($row['description']) ?></small><?php endif; ?></td><td><?= e($page==='items'?$row['supplier_name']:$row['phone']) ?></td><td><?= $page==='items'?money((int)$row['price_cents']):e($row[$page==='users'?'role':'comment']) ?></td><td class="actions"><a class="button small" href="index.php?page=<?= $page ?>&edit=<?= $row['id'] ?>#record-form">Edit</a><?php if($page==='users') password_reset_link((int)$row['id']); delete_form($page,(int)$row['id']); ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td class="empty" colspan="4">Your directory is empty. Add your first record.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel form-panel" id="record-form"><h2><?= $editId?'Edit':'Add' ?> <?= $page==='items'?'supplier item':($page==='users'?'user':'supplier') ?></h2><form method="post" class="stack"><?= token_field() ?><input type="hidden" name="action" value="<?= ['users'=>'save_user','suppliers'=>'save_supplier','items'=>'save_item'][$page] ?>"><input type="hidden" name="id" value="<?= e($editId??'') ?>">
<?php if($page==='items'): ?><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s): ?><option value="<?= $s['id'] ?>" <?= (int)($_POST['supplier_id']??$record['supplier_id']??$filterSupplier)===(int)$s['id']?'selected':'' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select></label><?php endif; ?>
<label>Name<input name="name" maxlength="<?= $page==='users'?100:150 ?>" required value="<?= input_value($record,'name') ?>" autocomplete="off"></label>
<?php if($page==='items'): ?><label>Description<textarea name="description" maxlength="2000"><?= input_value($record,'description') ?></textarea></label><label>Price (KM)<input name="price" type="number" min="0" max="9999999.99" step="0.01" required value="<?= e($_POST['price']??(isset($record['price_cents'])?number_format($record['price_cents']/100,2,'.',''):'')) ?>"></label>
<?php else: ?><label>Phone<input name="phone" type="tel" maxlength="50" value="<?= input_value($record,'phone') ?>"></label><?php if($page==='suppliers'): ?><label>Comment<textarea name="comment" maxlength="2000"><?= input_value($record,'comment') ?></textarea></label><?php else: ?><label>Role<select name="role"><?php foreach(['user','admin'] as $r): ?><option value="<?= $r ?>" <?= ($_POST['role']??$record['role']??'user')===$r?'selected':'' ?>><?= ucfirst($r) ?></option><?php endforeach; ?></select></label><?php endif; ?><label><?= $editId?'New password':'Password' ?><?= $page==='suppliers'?' (reserved for future supplier login)':'' ?><input type="password" name="password" minlength="10" maxlength="72" autocomplete="new-password" <?= $page==='users'&&!$editId?'required':'' ?>></label><small class="muted"><?= $editId?'Leave blank to keep the current password. ':'' ?>10–72 bytes. <?= $page==='suppliers'?'Optional. Supplier sign-in is not enabled yet.':'' ?></small><?php endif; ?>
<div class="form-actions"><button class="button primary">Save <?= $page==='items'?'item':($page==='users'?'user':'supplier') ?></button><?php if($editId): ?><a class="button" href="index.php?page=<?= $page ?>">Cancel</a><?php endif; ?></div></form></section></div>
<?php if($page==='users' && !empty($_GET['reset'])) require __DIR__.'/password-reset.php'; ?>
<?php elseif($page==='order_summary'): require __DIR__.'/order-summary.php'; elseif($page==='order'): require __DIR__.'/order-view.php'; endif; ?>
